pub const SECURE_BOOT_OTP_OFFSET:u16=0x20;pub const REF_OTP_IO_ERROR:u32=0xFFFF_0006;pub const REF_SECURE_BOOT_ALREADY_ENABLED:u32=0xF010_0003;
pub trait SecureBootOtp{type Error;fn read_secure_byte(&mut self,offset:u16)->Result<u8,Self::Error>;fn write_secure_byte(&mut self,offset:u16,value:u8)->Result<(),Self::Error>;}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum SecureBootEnable{EnabledNow,AlreadyEnabled(u8)}
pub fn ensure_secure_boot_enabled<I:SecureBootOtp>(io:&mut I)->Result<SecureBootEnable,I::Error>{let v=io.read_secure_byte(SECURE_BOOT_OTP_OFFSET)?;if v==0{io.write_secure_byte(SECURE_BOOT_OTP_OFFSET,0xFF)?;Ok(SecureBootEnable::EnabledNow)}else{Ok(SecureBootEnable::AlreadyEnabled(v))}}
pub fn read_redundant_secure_boot_marker<I:SecureBootOtp>(io:&mut I,out:&mut[u8])->Result<(),I::Error>{let a=io.read_secure_byte(SECURE_BOOT_OTP_OFFSET)?;let b=io.read_secure_byte(SECURE_BOOT_OTP_OFFSET)?;out.fill(0);if a.count_ones()>3||b.count_ones()>3{if let Some(first)=out.first_mut(){*first=0xFF}}Ok(())}
#[cfg(test)]mod tests{use super::*;struct O{v:u8,w:u8,n:u8}impl SecureBootOtp for O{type Error=();fn read_secure_byte(&mut self,_:u16)->Result<u8,()>{self.n+=1;Ok(self.v)}fn write_secure_byte(&mut self,_:u16,v:u8)->Result<(),()>{self.w=v;self.v=v;Ok(())}}#[test]fn enable(){let mut o=O{v:0,w:0,n:0};assert_eq!(ensure_secure_boot_enabled(&mut o),Ok(SecureBootEnable::EnabledNow));assert_eq!(o.w,0xff);let mut out=[7u8;4];o.v=0x0f;read_redundant_secure_boot_marker(&mut o,&mut out).unwrap();assert_eq!(out,[0xff,0,0,0]);assert_eq!(REF_OTP_IO_ERROR,0xffff0006);}}
